//////////////////////////////////////////////////////////////////////
// meaning-codes.bml — one meaning, many codes. A meaning is a symbol
// token the body already speaks (symbol-voice for the words, perception-
// symbols for what is not a word); its codes are its NL phrase, a short
// hash anchor of the symbol, and every tongue or script row
// the locale files carry. Every file named symbol-*.rows in the locale
// directory joins: symbol-words.rows and symbol-perception.rows carry
// english|fa|de|fr|pt|ro (the second for the sound around the words),
// symbol-jungle.rows carries the jungle's own tongues, and
// symbol-scripts.rows (english|he|zh|ja) joins the moment the resident
// writes it (observe/hearth-scripts-run.fk). Each file's first line names
// its code kinds after the english key.
// mc-resolve-all returns every matching meaning. The round-trip check proves
// membership for each present code, preserving shared codes and alternate senses.
// The short anchor belongs to this codebook; kernel composition identity has
// its own representation. These lookup functions run when explicitly called;
// the local model's decoder continues to predict its own vocabulary token IDs.
// The bytes
// of each code beside the NL phrase measure what speaking in codes
// compresses. A code kind with no row yet is absent and says so.
//
// Two rosters, one grammar. mc-meanings() is what a HEARD LINE resolves
// against, so a spoken "still" stays the word and does not become the room
// being still; ps-symbols() is what a PERCEPTION resolves against, and
// mc-resolve-among walks whichever roster the caller is reading in. Every
// symbol of either roster addresses (mc-anchor) and speaks (mc-say-in) the
// same way — the roster decides what a code may mean, never how it is said.
//
// The rows are read and split ONCE. Form holds no mutable state, so "read
// once" is not a cache: mc-table() is the door that reads, and every walker
// visiting more than one meaning takes that table as an argument and hands
// it down its own recursion. mc-book() is the same move one level up —
// every meaning's codes computed once — so resolving a code is a walk over
// answers instead of a re-derivation of them. A caller with many meanings
// to ask about takes mc-table()/mc-codes-in rather than mc-codes per symbol.
// preludes: form/form-stdlib/symbol-voice.bml form/form-stdlib/perception-symbols.bml form/form-stdlib/form-fs.fk form/form-stdlib/str-byte-at.fk form/form-stdlib/sha256.fk form/form-stdlib/hex.fk form/form-stdlib/spool-bell-transport.fk
//////////////////////////////////////////////////////////////////////
section [form.bml] {
    class FormMeaningCodes {
        field MCScripts = "form/form-stdlib/locale-rows/symbol-scripts.rows";
        def mc-dir() = "form/form-stdlib/locale-rows";
        def mc-text(t) = if nothing?(t) then "" else t;
        def mc-cat(parts) = sv-cat(parts);
        def mc-meanings() = list("you", "me", "us", "US", "WE", "DO", "BE", "SEE", "say", "tell", "offer", "admit", "refuse", "folded", "witness", "release", "nothing", "node", "gas", "water", "ice", "spent", "landed", "glass", "teaching", "gold", "seam", "next", "r", "e", "c", "Q", "adapter", "loss", "whole", "pairs");
        // the perceived things that are not words carry their English phrase in perception-symbols;
        // everything else is the fixed voice's. A symbol neither roster names has no phrase and says so.
        def mc-nl(sym) = mc-nl-of(sym, ps-nl(sym));
        def mc-nl-of(sym, perceived) = if gt(str_len(perceived), 0) then perceived else sv-fixed(sym);
        // the anchor is the symbol itself, no tongue privileged
        def mc-node(text) = substring(hex-encode(sha256(sbt-bytes-of(text, 0, str_len(text), list()))), 0, 8);
        def mc-anchor(sym) = mc-node(sym);
        // ---- the rows, read once ----
        // row files: header "english|k1|k2|..." then "phrase|c1|c2|..."
        def mc-lines(path) = split-on(mc-text(read_file(path)), byte_to_str(10));
        def mc-trimmed(cells) = if eq(len(cells), 0) then list() else cons(trim(head(cells)), mc-trimmed(tail(cells)));
        def mc-cells(line) = mc-trimmed(split-on(line, "|"));
        def mc-rows-of(lines) = if eq(len(lines), 0) then list() else cons(mc-cells(head(lines)), mc-rows-of(tail(lines)));
        // one file's entry: (kinds rows) — the header's kinds after the english key, every row already in cells
        def mc-file-table(path) = mc-file-table-of(mc-lines(path));
        def mc-file-table-of(lines) = if eq(len(lines), 0) then list(list(), list()) else list(tail(split-on(head(lines), "|")), mc-rows-of(tail(lines)));
        def mc-files() = mc-rows-files(fs-list(mc-dir()));
        def mc-rows-files(names) = if eq(len(names), 0) then list() else if and(eq(str_find(head(names), "symbol-", 0), 0), ge(str_find(head(names), ".rows", 0), 0)) then cons(fs-path-join(mc-dir(), head(names)), mc-rows-files(tail(names))) else mc-rows-files(tail(names));
        // THE TABLE: every locale file read once and split once
        def mc-table() = mc-table-of(mc-files());
        def mc-table-of(paths) = if eq(len(paths), 0) then list() else cons(mc-file-table(head(paths)), mc-table-of(tail(paths)));
        // ---- one phrase's row, over rows already in cells ----
        // the resident keyed some rows without the article ("gift" for "a gift"): try the phrase, then the phrase past a leading "a " or "the "
        def mc-bare(phrase) = if eq(str_find(phrase, "a ", 0), 0) then substring(phrase, 2, str_len(phrase)) else if eq(str_find(phrase, "the ", 0), 0) then substring(phrase, 4, str_len(phrase)) else phrase;
        // a row matches on ANY column: every tongue keys a row at the same level
        def mc-cell-match?(cells, phrase) = if eq(len(cells), 0) then 0 else if str_eq(head(cells), phrase) then 1 else mc-cell-match?(tail(cells), phrase);
        def mc-find-row(rows, phrase) = if eq(len(rows), 0) then list() else if and(ge(len(head(rows)), 2), eq(mc-cell-match?(head(rows), phrase), 1)) then head(rows) else mc-find-row(tail(rows), phrase);
        def mc-row-for(rows, phrase) {
            let exact = if eq(str_len(phrase), 0) then list() else mc-find-row(rows, phrase);
            if gt(len(exact), 0) then exact else if or(eq(str_len(phrase), 0), str_eq(mc-bare(phrase), phrase)) then list() else mc-find-row(rows, mc-bare(phrase));
        }
        def mc-zip(kinds, cells) = if or(eq(len(kinds), 0), eq(len(cells), 0)) then list() else cons(list(head(kinds), head(cells)), mc-zip(tail(kinds), tail(cells)));
        def mc-entry-codes(entry, phrase) = mc-entry-row(entry, mc-row-for(nth(entry, 1), phrase));
        def mc-entry-row(entry, row) = if eq(len(row), 0) then list() else mc-zip(head(entry), tail(row));
        def mc-table-codes(tbl, phrase) = if eq(len(tbl), 0) then list() else append(mc-entry-codes(head(tbl), phrase), mc-table-codes(tail(tbl), phrase));
        // every code of a meaning: (kind code) rows; absent kinds are simply not present
        def mc-codes-in(tbl, sym) = mc-codes-nl(tbl, sym, mc-nl(sym));
        def mc-codes-nl(tbl, sym, nl) = append(list(list("symbol", sym), list("nl", nl), list("node", mc-anchor(sym))), mc-table-codes(tbl, nl));
        def mc-codes(sym) = mc-codes-in(mc-table(), sym);
        // ---- the codebook: every meaning's codes, computed once ----
        def mc-book-of(syms, tbl) = if eq(len(syms), 0) then list() else cons(list(head(syms), mc-codes-in(tbl, head(syms))), mc-book-of(tail(syms), tbl));
        def mc-book() = mc-book-of(mc-meanings(), mc-table());
        // speak a meaning in any tongue the rows carry (the english phrase is kind "nl")
        def mc-code-of(codes, kind) = if eq(len(codes), 0) then "" else if str_eq(head(head(codes)), kind) then nth(head(codes), 1) else mc-code-of(tail(codes), kind);
        def mc-say-in-tbl(tbl, sym, kind) = mc-code-of(mc-codes-in(tbl, sym), kind);
        def mc-say-in(sym, kind) = mc-say-in-tbl(mc-table(), sym, kind);
        def mc-line-in(tokens, kind) = mc-line-in-tbl(mc-table(), tokens, kind);
        def mc-line-in-tbl(tbl, tokens, kind) = if eq(len(tokens), 0) then "" else mc-cat(list(mc-say-in-or(tbl, head(tokens), kind), if eq(len(tail(tokens)), 0) then "" else ", ", mc-line-in-tbl(tbl, tail(tokens), kind)));
        def mc-say-in-or(tbl, tok, kind) = mc-said-or-asked(mc-say-in-tbl(tbl, tok, kind), tok);
        def mc-said-or-asked(w, tok) = if gt(str_len(w), 0) then w else mc-cat(list("[", tok, "?]"));
        def mc-has-code?(codes, code) = if eq(len(codes), 0) then 0 else if str_eq(nth(head(codes), 1), code) then 1 else mc-has-code?(tail(codes), code);
        // a code may carry several meanings (the resident gave one Persian word for said and told):
        // resolve answers every meaning that carries it; the round trip is membership; the
        // collisions are listed as the price of compression, never hidden
        def mc-resolve-book(book, code) = if eq(len(book), 0) then list() else if eq(mc-has-code?(nth(head(book), 1), code), 1) then cons(head(head(book)), mc-resolve-book(tail(book), code)) else mc-resolve-book(tail(book), code);
        def mc-resolve-in(book, code) = mc-resolve-book(book, trim(code));
        def mc-resolve-all(code) = mc-resolve-in(mc-book(), code);
        // the same resolve read in another roster: a perception's codes answer perception symbols
        def mc-resolve-among(syms, code) = mc-resolve-in(mc-book-of(syms, mc-table()), code);
        def mc-perceived-all(code) = mc-resolve-among(ps-symbols(), code);
        def mc-perceived(code) = mc-first-or-none(mc-perceived-all(code));
        def mc-first-or-none(all) = if eq(len(all), 0) then "" else head(all);
        def mc-resolve(code) = mc-first-or-none(mc-resolve-all(code));
        def mc-member?(xs, x) = if eq(len(xs), 0) then 0 else if str_eq(head(xs), x) then 1 else mc-member?(tail(xs), x);
        // round trip: every present code of sym resolves to sym, read against the book of meanings
        def mc-round-book?(book, sym, codes) = if eq(len(codes), 0) then 1 else if eq(str_len(nth(head(codes), 1)), 0) then mc-round-book?(book, sym, tail(codes)) else if eq(mc-member?(mc-resolve-in(book, nth(head(codes), 1)), sym), 1) then mc-round-book?(book, sym, tail(codes)) else 0;
        def mc-round-trip?(sym) = mc-round-one?(mc-table(), sym);
        def mc-round-one?(tbl, sym) = mc-round-book?(mc-book-of(mc-meanings(), tbl), sym, mc-codes-in(tbl, sym));
        def mc-all-round?(syms) = mc-all-round-tbl?(mc-table(), syms);
        def mc-all-round-tbl?(tbl, syms) = mc-all-round-go?(mc-book-of(mc-meanings(), tbl), tbl, syms);
        def mc-all-round-go?(book, tbl, syms) = if eq(len(syms), 0) then 1 else if eq(mc-round-book?(book, head(syms), mc-codes-in(tbl, head(syms))), 1) then mc-all-round-go?(book, tbl, tail(syms)) else 0;
        def mc-collisions(syms, acc) = mc-collisions-tbl(mc-table(), syms, acc);
        def mc-collisions-tbl(tbl, syms, acc) = mc-collisions-go(mc-book-of(mc-meanings(), tbl), tbl, syms, acc);
        def mc-collisions-go(book, tbl, syms, acc) = if eq(len(syms), 0) then acc else mc-collisions-go(book, tbl, tail(syms), mc-coll-codes(book, mc-codes-in(tbl, head(syms)), acc));
        def mc-coll-codes(book, codes, acc) = if eq(len(codes), 0) then acc else mc-coll-codes(book, tail(codes), mc-coll-one(book, nth(head(codes), 1), acc));
        def mc-coll-one(book, code, acc) = if eq(str_len(code), 0) then acc else mc-coll-add(code, mc-resolve-in(book, code), acc);
        def mc-coll-add(code, all, acc) = if gt(len(all), 1) then cons(list(code, all), acc) else acc;
        def mc-join(xs) = if eq(len(xs), 0) then "" else if eq(len(tail(xs)), 0) then head(xs) else mc-cat(list(head(xs), ",", mc-join(tail(xs))));
        // compression: the shortest present code against the NL phrase, in bytes
        def mc-shortest(codes, best) = if eq(len(codes), 0) then best else mc-shortest(tail(codes), if and(gt(str_len(nth(head(codes), 1)), 0), or(eq(len(best), 0), lt(str_len(nth(head(codes), 1)), str_len(nth(best, 1))))) then head(codes) else best);
        def mc-line(codes) = if eq(len(codes), 0) then "" else mc-cat(list(head(head(codes)), ":", if eq(str_len(nth(head(codes), 1)), 0) then "absent" else nth(head(codes), 1), " ", mc-line(tail(codes))));
    }
    0;
}

//////////////////////////////////////////////////////////////////////
// symbol-voice.bml — a symbol line the body expands to natural language
// for free. The vocabulary is what the body already answers with: the five
// altitudes (you me us US WE), the three modes (DO BE SEE), the channel
// kinds, the ack values, the glass evidence marks (* + # ~ ?), the phases,
// the atlas tiles — and every fresh word of the corpus, whose row already
// carries its own sentence. A token the body does not know comes back as
// [word?]: an offer for a row, never a guess. key:value stays key = value.
// preludes: form/form-stdlib/core.fk form/form-stdlib/line-grammar.fk
//////////////////////////////////////////////////////////////////////
section [form.bml] {
    class FormSymbolVoice {
        field SVCorpus = "learn/homecoming-distillation-corpus.fk";
        def sv-cat(parts) = if eq(len(parts), 0) then "" else str_concat(head(parts), sv-cat(tail(parts)));
        def sv-text(t) = if nothing?(t) then "" else t;
        def sv-fixed(w) = if str_eq(w, "you") then "the body" else if str_eq(w, "me") then "Urs" else if str_eq(w, "us") then "this sitting" else if str_eq(w, "US") then "the sittings of today" else if str_eq(w, "WE") then "the collective"
            else if str_eq(w, "DO") then "did" else if str_eq(w, "BE") then "stands" else if str_eq(w, "SEE") then "observed"
            else if str_eq(w, "say") then "said" else if str_eq(w, "tell") then "told" else if str_eq(w, "offer") then "offered" else if str_eq(w, "admit") then "admitted" else if str_eq(w, "refuse") then "refused" else if str_eq(w, "folded") then "folded" else if str_eq(w, "witness") then "witnessed" else if str_eq(w, "release") then "released"
            else if str_eq(w, "nothing") then "not yet" else if str_eq(w, "node") then "a node" else if str_eq(w, "gas") then "gas, source only" else if str_eq(w, "water") then "water, fresh ice" else if str_eq(w, "ice") then "ice, frozen"
            else if str_eq(w, "refused") then "refused" else if str_eq(w, "published") then "published" else if str_eq(w, "f16") then "half floats" else if str_eq(w, "f32") then "floats" else if str_eq(w, "spent") then "the patience was spent" else if str_eq(w, "landed") then "landed on main" else if str_eq(w, "band") then "the band answers" else if str_eq(w, "glass") then "on the glass" else if str_eq(w, "teaching") then "the most surprising teaching:" else if str_eq(w, "gold") then "discomfort became gold at:" else if str_eq(w, "seam") then "an honest seam:" else if str_eq(w, "next") then "the next stone:"
            else if str_eq(w, "lora") then "the adapter lane" else if str_eq(w, "adapter") then "the adapter the body trained" else if str_eq(w, "loss") then "training loss" else if str_eq(w, "iter") then "iteration" else if str_eq(w, "rank") then "rank" else if str_eq(w, "pairs") then "low-rank pairs" else if str_eq(w, "whole") then "structurally whole" else if str_eq(w, "layers") then "layers touched" else if str_eq(w, "dtype") then "stored as" else if str_eq(w, "bytes") then "bytes" else if str_eq(w, "tokens-sec") then "tokens per second" else if str_eq(w, "O") then "the walk economy" else if str_eq(w, "r") then "a gift" else if str_eq(w, "e") then "a step" else if str_eq(w, "c") then "a cell" else if str_eq(w, "Q") then "a request" else if str_eq(w, "T") then "the token position" else if str_eq(w, "G") then "glass arrival" else "";
        def sv-mark(c) = if eq(c, 42) then "physically live" else if eq(c, 43) then "derived" else if eq(c, 35) then "from a catalog" else if eq(c, 126) then "declared" else if eq(c, 63) then "missing" else "";
        def sv-hex?(s, i) = if ge(i, str_len(s)) then 1 else if or(and(ge(str_byte_at(s, i), 48), le(str_byte_at(s, i), 57)), and(ge(str_byte_at(s, i), 97), le(str_byte_at(s, i), 102))) then sv-hex?(s, add(i, 1)) else 0;
        def sv-digits?(s, i) = if ge(i, str_len(s)) then 1 else if and(ge(str_byte_at(s, i), 48), le(str_byte_at(s, i), 57)) then sv-digits?(s, add(i, 1)) else 0;
        def sv-corpus-cmd(w) = sv-cat(list("grep -m1 -B2 '^ *\"", w, "\"$' ", SVCorpus(), " | head -2 | grep -o '\"[a-z]*\"' | tr -d '\"' | tr '\\n' ' '"));
        def sv-corpus(w) = trim(sv-text(host-exec(sv-corpus-cmd(w), "")));
        def sv-has-letter?(s, i) = if ge(i, str_len(s)) then 0 else if and(ge(str_byte_at(s, i), 97), le(str_byte_at(s, i), 102)) then 1 else sv-has-letter?(s, add(i, 1));
        def sv-numberish?(s, i) = if ge(i, str_len(s)) then 1 else if or(and(ge(str_byte_at(s, i), 48), le(str_byte_at(s, i), 57)), or(eq(str_byte_at(s, i), 46), eq(str_byte_at(s, i), 45))) then sv-numberish?(s, add(i, 1)) else 0;
        def sv-word(w) {
            let fixed = sv-fixed(w);
            if gt(str_len(fixed), 0) then fixed
            else if and(ge(str_len(w), 8), and(eq(sv-hex?(w, 0), 1), eq(sv-has-letter?(w, 0), 1))) then str_concat("node ", w)
            else if eq(sv-numberish?(w, 0), 1) then w
            else sv-word-corpus(w, sv-corpus(w));
        }
        def sv-word-corpus(w, q) = if eq(str_len(q), 0) then sv-cat(list("[", w, "?]")) else sv-cat(list(w, ", the word for: ", q));
        def sv-token(t) {
            let last = if eq(str_len(t), 0) then 0 else str_byte_at(t, sub(str_len(t), 1));
            let colon = str_find(t, ":", 0);
            if eq(str_len(t), 0) then ""
            else if and(gt(str_len(t), 1), gt(str_len(sv-mark(last)), 0)) then sv-cat(list(sv-token(substring(t, 0, sub(str_len(t), 1))), " (", sv-mark(last), ")"))
            else if eq(str_len(t), 1) then if gt(str_len(sv-mark(last)), 0) then sv-mark(last) else sv-word(t)
            else if ge(colon, 0) then sv-cat(list(sv-word(substring(t, 0, colon)), " = ", sv-word(substring(t, add(colon, 1), str_len(t)))))
            else sv-word(t);
        }
        def sv-join(parts) = if eq(len(parts), 0) then "" else if eq(len(tail(parts)), 0) then head(parts) else sv-cat(list(head(parts), if or(str_eq(head(tail(parts)), ". "), str_eq(head(parts), ". ")) then "" else ", ", sv-join(tail(parts))));
        def sv-tokens(ws) = if eq(len(ws), 0) then list() else if eq(str_len(trim(head(ws))), 0) then sv-tokens(tail(ws)) else cons(if str_eq(head(ws), "|") then ". " else sv-token(trim(head(ws))), sv-tokens(tail(ws)));
        def sv-say(line) = sv-join(sv-tokens(split-on(line, " ")));
    }
    0;
}

//////////////////////////////////////////////////////////////////////
//
// perception-symbols.bml — the perceived things that are NOT words.
//
// A heard line already resolves to symbols (meaning-codes, ear.symbols). Everything
// else the room gives arrives as prose in a row's value: "still", "-50 dBFS, airy,
// steady 3 s", "asleep — resting", a pitch in hertz. This cell gives each of those a
// symbol of its own, so the whole perception — the words AND the sound around them —
// is one line of symbols the body can carry, address and say in any tongue.
//
// Four families, twenty symbols:
//   room-kind    still voice tone knock noise      what kind of sound this is
//   room-tone    hiss air rumble                   the colour of the room's own quiet
//   ear-state    asleep deaf silent speaking heard the ear's own condition
//   voice-manner cadence intonation pitch volume expression stillness resonance
//
// The symbols are read OFF the sensors' own rows, never invented beside them: the
// kind is room.kind's word, the colour is the word room.tone already prints, the
// state is the word ear.state opens with, and a manner stands only when its own
// prosody row carries a reading. A manner whose row is absent is NOT perceived and
// does not enter the line — an axis the body has is not a thing the body senses.
//
// Node ids and tongues are meaning-codes' work, not this cell's: mc-anchor(sym)
// addresses a symbol, mc-say-in(sym, kind) says it, and mc-nl reads its English
// phrase from here. This cell stays light on purpose, so the glass, which preludes it
// and reads it every frame, never pays for a hash to paint a word.
//
// preludes: form/form-stdlib/core.fk form/form-stdlib/line-grammar.fk form/form-stdlib/form-glass-observer.bml
//
//////////////////////////////////////////////////////////////////////

section [form.bml] {
    class FormPerceptionSymbols {
        field PSSchema = "perception-symbols-v1";

        // ── the roster ────────────────────────────────────────────────────
        def ps-kinds() = list("still", "voice", "tone", "knock", "noise");
        def ps-colours() = list("hiss", "air", "rumble");
        def ps-states() = list("asleep", "deaf", "silent", "speaking", "heard");
        def ps-manners() = list("cadence", "intonation", "pitch", "volume", "expression", "stillness", "resonance");
        def ps-symbols() = append(ps-kinds(), append(ps-colours(), append(ps-states(), ps-manners())));
        def ps-member?(xs, x) = if eq(len(xs), 0) then 0 else if str_eq(head(xs), x) then 1 else ps-member?(tail(xs), x);
        def ps-symbol?(sym) = ps-member?(ps-symbols(), sym);
        // a symbol without its family is a token; the family says what it is a symbol OF
        def ps-family(sym) = if eq(ps-member?(ps-kinds(), sym), 1) then "room-kind" else if eq(ps-member?(ps-colours(), sym), 1) then "room-tone" else if eq(ps-member?(ps-states(), sym), 1) then "ear-state" else if eq(ps-member?(ps-manners(), sym), 1) then "voice-manner" else "";
        def ps-families() = list("room-kind", "room-tone", "ear-state", "voice-manner");

        // ── the English phrase of each symbol; meaning-codes keys the locale rows on it ──
        def ps-nl(sym) = if str_eq(sym, "still") then "a still room" else if str_eq(sym, "voice") then "a voice" else if str_eq(sym, "tone") then "a held tone" else if str_eq(sym, "knock") then "a knock" else if str_eq(sym, "noise") then "noise"
            else if str_eq(sym, "hiss") then "hissy" else if str_eq(sym, "air") then "airy" else if str_eq(sym, "rumble") then "a low rumble"
            else if str_eq(sym, "asleep") then "the ear sleeps" else if str_eq(sym, "deaf") then "the ear hears nothing" else if str_eq(sym, "silent") then "under the speech floor" else if str_eq(sym, "speaking") then "a line is open" else if str_eq(sym, "heard") then "a line closed"
            else if str_eq(sym, "cadence") then "the pace of the speaking" else if str_eq(sym, "intonation") then "where the phrase went" else if str_eq(sym, "pitch") then "the voice's pitch" else if str_eq(sym, "volume") then "the room's level" else if str_eq(sym, "expression") then "how much the delivery lives" else if str_eq(sym, "stillness") then "the share that was quiet" else if str_eq(sym, "resonance") then "how the sound falls away" else "";

        // ── reading a perceived thing off a sensor's own row value ────────
        def ps-cat(parts) = if eq(len(parts), 0) then "" else str_concat(head(parts), ps-cat(tail(parts)));
        def ps-has?(text, needle) = if lt(str_find(text, needle, 0), 0) then 0 else 1;
        // room.kind's value IS the kind word the organ decided
        def ps-kind-of(value) = ps-kind-word(trim(value));
        def ps-kind-word(w) = if eq(ps-member?(ps-kinds(), w), 1) then w else "";
        // room.tone prints its colour between the level and the steadiness: "-50 dBFS, airy, steady 3 s"
        def ps-colour-of(value) = if eq(ps-has?(value, "hissy"), 1) then "hiss" else if eq(ps-has?(value, "airy"), 1) then "air" else if eq(ps-has?(value, "rumble"), 1) then "rumble" else "";
        // ear.state opens with its state word, then an em dash and the verse's own word
        def ps-state-of(value) = ps-state-word(trim(ps-first-word(trim(value))));
        def ps-first-word(value) = ps-cut(value, str_find(value, " ", 0));
        def ps-cut(value, at) = if lt(at, 0) then value else substring(value, 0, at);
        def ps-state-word(w) = if eq(ps-member?(ps-states(), w), 1) then w else "";
        // a manner is named by its own prosody row's second segment: prosody.cadence.rate -> cadence
        def ps-manner-of(id) = ps-manner-at(split-on(id, "."));
        def ps-manner-at(parts) = if lt(len(parts), 2) then "" else if not(str_eq(head(parts), "prosody")) then "" else ps-manner-word(nth(parts, 1));
        def ps-manner-word(w) = if eq(ps-member?(ps-manners(), w), 1) then w else "";
        // the one row that carries each manner's reading; the others of that axis stand beside it in the frame
        def ps-manner-door(sym) = if str_eq(sym, "cadence") then "prosody.cadence.rate" else if str_eq(sym, "intonation") then "prosody.intonation.span" else if str_eq(sym, "pitch") then "prosody.pitch" else if str_eq(sym, "volume") then "prosody.volume" else if str_eq(sym, "expression") then "prosody.expression.level" else if str_eq(sym, "stillness") then "prosody.stillness" else if str_eq(sym, "resonance") then "prosody.resonance.decay" else "";

        // ── one perceived thing: its symbol, its family, what was read, the door it was read at ──
        def ps-seen(sym, reading, door) = list(sym, ps-family(sym), reading, door);
        def ps-seen-sym(s) = head(s);
        def ps-seen-family(s) = nth(s, 1);
        def ps-seen-reading(s) = nth(s, 2);
        def ps-seen-door(s) = nth(s, 3);
        def ps-see-one(sym, reading, door) = if eq(str_len(sym), 0) then list() else list(ps-seen(sym, reading, door));

        // ── the rows themselves ───────────────────────────────────────────
        def ps-row(rows, id) = if eq(len(rows), 0) then list() else if str_eq(fgo-id(head(rows)), id) then head(rows) else ps-row(tail(rows), id);
        def ps-text(rows, id) = ps-text-of(ps-row(rows, id));
        // A confident value from a publisher that stopped giving is NOT a perception. The glass
        // marks every row it takes from a frame older than three of that sensor's own declared
        // cadences as silent (fgsr-rows-or-absent), and a row wearing that mark reads as nothing
        // here. Witnessed 2026-09-07: no room sensor was standing, its last frame still said
        // "still, airy" from minutes before, and the ear beside it was hearing a whole sentence --
        // a dead room's last words were becoming a live symbol until this refused them.
        def ps-live?(r) = if eq(len(r), 0) then 0 else if eq(fgo-present?(r), 0) then 0 else if str_eq(fgo-evidence(r), "silent") then 0 else if str_eq(fgo-lifecycle(r), "silent") then 0 else 1;
        def ps-text-of(r) = if eq(ps-live?(r), 1) then fgo-text-value(r) else "";
        // an absent row reads as nothing, never as a zero: a door that answered nothing is not a measurement
        def ps-reading-of(r) = if eq(ps-live?(r), 0) then "" else if str_eq(fgo-value-kind(r), "int") then ps-cat(list(int_to_str(fgo-int-value(r)), " ", fgo-unit(r))) else fgo-text-value(r);
        def ps-reading(rows, id) = ps-reading-of(ps-row(rows, id));

        // ── the whole perception, in the order a room is read ─────────────
        def ps-see-state(rows) = ps-see-one(ps-state-of(ps-text(rows, "ear.state")), ps-text(rows, "ear.state"), "ear.state");
        def ps-see-kind(rows) = ps-see-one(ps-kind-of(ps-text(rows, "room.kind")), ps-text(rows, "room.kind"), "room.kind");
        def ps-see-colour(rows) = ps-see-one(ps-colour-of(ps-text(rows, "room.tone")), ps-text(rows, "room.tone"), "room.tone");
        def ps-see-manner(rows, sym) = ps-see-manner-at(sym, ps-manner-door(sym), ps-reading(rows, ps-manner-door(sym)));
        def ps-see-manner-at(sym, door, reading) = if eq(str_len(reading), 0) then list() else list(ps-seen(sym, reading, door));
        def ps-see-manners(rows, syms) = if eq(len(syms), 0) then list() else append(ps-see-manner(rows, head(syms)), ps-see-manners(rows, tail(syms)));
        def ps-perceive(rows) = append(ps-see-state(rows), append(ps-see-kind(rows), append(ps-see-colour(rows), ps-see-manners(rows, ps-manners()))));

        // what the body has an axis for and is NOT sensing now; named, so a short line is not read as a poor room
        def ps-unperceived(rows, syms) = if eq(len(syms), 0) then list() else if gt(len(ps-see-manner(rows, head(syms))), 0) then ps-unperceived(rows, tail(syms)) else cons(head(syms), ps-unperceived(rows, tail(syms)));
        def ps-unsensed(rows) = ps-unperceived(rows, ps-manners());

        // ── the line ──────────────────────────────────────────────────────
        def ps-syms(seen) = if eq(len(seen), 0) then list() else cons(ps-seen-sym(head(seen)), ps-syms(tail(seen)));
        def ps-join(xs, sep) = if eq(len(xs), 0) then "" else if eq(len(tail(xs)), 0) then head(xs) else ps-cat(list(head(xs), sep, ps-join(tail(xs), sep)));
        def ps-line(seen) = ps-join(ps-syms(seen), " ");
        def ps-line-of(rows) = ps-line(ps-perceive(rows));
        def ps-reading-line(seen) = if eq(len(seen), 0) then "" else ps-cat(list(ps-seen-sym(head(seen)), "=", ps-seen-reading(head(seen)), if eq(len(tail(seen)), 0) then "" else "  ", ps-reading-line(tail(seen))));
    }
    0;
}
